import {MATERIALS,MATERIAL_BY_ID,materialName,textureAsset,applyMaterial} from './material-library.mjs?v=cad18';
export function installMaterials({scene,current,getProject,commit,toast,advanced}){
 const $=s=>document.querySelector(s),dialog=$('#material-dialog');let target='front',choice='',category='Все',roughness=null;
 const names={front:'Фасады модуля',body:'Корпус модуля',top:'Столешница',handle:'Ручки модуля',part:'Выбранная деталь',matching:'Такие детали во всём проекте',edge:'Кромка детали'};
 const selected=()=>scene.parts().find(p=>p.id===advanced.selectedPart());
 function render(){const m=current();const slider=document.querySelector('[data-advanced=roughness]');if(slider){slider.disabled=!!m?.locked||!!m?.frontMaterial;slider.title=m?.frontMaterial?'Шероховатость этого материала настраивается в библиотеке отделки':'';}document.querySelectorAll('[data-material-open]').forEach(b=>{const t=b.dataset.materialOpen;const p=selected();b.disabled=!m||m.locked||(['part','edge'].includes(t)&&!p);const id=['part','edge'].includes(t)?m?.details?.[p?.id]?.[t==='edge'?'edgeMaterial':'material']:m?.[t+'Material'];const label=b.querySelector('small');if(label)label.textContent=materialName(id)||(t==='part'?'Как у модуля':t==='edge'?'Без отдельной отделки':'Текущая отделка');});}
 function cards(){const list=MATERIALS.filter(m=>(category==='Все'||m.category===category)&&(m.name+' '+m.category).toLowerCase().includes($('#material-search').value.toLowerCase()));$('#material-cards').replaceChildren();for(const m of list){const b=document.createElement('button');b.type='button';b.className='material-card';b.dataset.materialId=m.id;b.setAttribute('aria-pressed',String(choice===m.id));const tile=document.createElement('span');tile.className='material-tile';tile.style.backgroundColor=m.color;const asset=textureAsset(m.type);if(asset){tile.style.backgroundImage=`url('../assets/pbr/${asset}_diff.jpg')`;tile.style.backgroundBlendMode='multiply';if(m.type==='walnut')tile.style.backgroundSize='180%';}else tile.classList.add(m.category==='Металл'?'sample-metal':m.category==='Стекло'?'sample-glass':'sample-paint');const name=document.createElement('strong');name.textContent=m.name;const type=document.createElement('small');type.textContent=m.category;b.append(tile,name,type);b.onclick=()=>{choice=m.id;roughness=null;cards();preview();};$('#material-cards').append(b);}$('#material-count').textContent=`${list.length} образцов`;}
 function preview(){const p=MATERIAL_BY_ID[choice];$('#material-preview-title').textContent=p?.name||'Отделка модуля';$('#material-description').textContent=p?.description||'Сбросить индивидуальный материал и использовать настройки модуля.';$('#material-preview').hidden=!p;$('#material-roughness-row').hidden=!p||target==='edge';if(p){$('#material-roughness').value=roughness??p.roughness;$('#material-roughness-value').textContent=Number(roughness??p.roughness).toFixed(2);$('#material-preview').src=scene.materialSample(p.id,roughness==null?{}:{roughness});}$('#material-apply').textContent=choice?'Применить материал':'Сбросить материал';}
 function open(t){const m=current(),p=selected();if(!m||m.locked)return;if(['part','edge'].includes(t)&&!p)return;target=t;
 choice=['part','edge'].includes(t)?m.details?.[p.id]?.[t==='edge'?'edgeMaterial':'material']||'':m[t+'Material']||'';
 roughness=t==='part'?(m.details?.[p.id]?.roughness??null):(m[t+'Roughness']??null);$('#material-target').textContent=names[t]+(p&&['part','edge'].includes(t)?' · '+p.label:'');
 $('#material-scope').hidden=t!=='part';$('#material-scope').value='part';category='Все';$('#material-filter').value='Все';$('#material-search').value='';cards();dialog.showModal();preview();}
 document.querySelectorAll('[data-material-open]').forEach(b=>b.onclick=()=>open(b.dataset.materialOpen));
 $('#material-filter').innerHTML=['Все',...new Set(MATERIALS.map(m=>m.category))].map(c=>`<option>${c}</option>`).join('');$('#material-filter').onchange=e=>{category=e.target.value;cards();};$('#material-search').oninput=cards;
 $('#material-roughness').oninput=e=>{roughness=Number(e.target.value);preview();};
 for(const key of ['floorProfile','wallProfile','backsplashProfile']){const select=document.querySelector(`[data-room="${key}"]`);select.innerHTML='<option value="">Базовая отделка комнаты</option>'+MATERIALS.filter(m=>['Дерево','Камень','Эмаль'].includes(m.category)).map(m=>`<option value="${m.id}">${m.name}</option>`).join('');}
 $('#material-close').onclick=()=>dialog.close();$('#material-inherit').onclick=()=>{choice='';cards();preview();};
 $('#material-apply').onclick=()=>{const m=current(),p=selected();if(!m||m.locked)return;let count=0;
  if(target==='edge'){if(!p)return;m.details||={};m.details[p.id]||={};if(choice){m.details[p.id].edgeMaterial=choice;m.details[p.id].edgeThickness??=1;}else delete m.details[p.id].edgeMaterial;count=1;}
  else count=applyMaterial(getProject().modules,m.id,p?.id,p?.kind,target==='part'?$('#material-scope').value:target,choice,module=>scene.partsFor(module.id));
  if(!count)return;if(choice&&roughness!=null&&target!=='edge'){if(target==='part'){for(const module of getProject().modules){if(module.locked||($('#material-scope').value==='part'&&module.id!==m.id))continue;for(const item of scene.partsFor(module.id)){if(item.kind===p.kind&&($('#material-scope').value==='matching'||item.id===p.id)){module.details[item.id].roughness=roughness;}}}}else m[target+'Roughness']=roughness;}dialog.close();commit({rebuild:true});toast(`Материал применён · ${count} ${target==='part'||target==='edge'?'деталей':'модулей'}`);render();
 };
 $('#part-focus').onclick=()=>{scene.focusPart();};
 $('#part-isolate').onclick=()=>{scene.toggleIsolation();$('#part-isolate').setAttribute('aria-pressed',String(!!scene.isolatedPart));};
 return {render,open};
}
